"""Synthetic RSD fixtures generated by hash-pinned source methods, no iPhone."""
import ast
import asyncio
import hashlib
import importlib.util
import sys
import uuid
from pathlib import Path
import construct
import hyperframe
from hyperframe.frame import DataFrame, HeadersFrame, SettingsFrame, WindowUpdateFrame
from reference_source import reference_file

assert construct.__version__ == '2.10.70'
assert hyperframe.__version__ == '6.1.0'
spec = importlib.util.spec_from_file_location('rsd_reference_xpc', reference_file('xpc_message.py'))
xpc = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = xpc
spec.loader.exec_module(xpc)
remote = reference_file('remotexpc.py')
rsd_path = Path('research/pymobiledevice3/pymobiledevice3/remote/remote_service_discovery.py')
assert hashlib.sha256(rsd_path.read_bytes()).hexdigest() == '654d4c2cdb6876d0e0e0035e07ffeaa0b2db2e1d576c4b19179823d9b48a32cf'

def methods(path, class_name, names):
    tree = ast.parse(path.read_text())
    cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == class_name)
    selected = [n for n in cls.body if isinstance(n, (ast.AsyncFunctionDef, ast.FunctionDef)) and n.name in names]
    assert {n.name for n in selected} == set(names)
    for method in selected:  # source body unchanged; remove annotations/decorators only
        method.returns = None
        method.decorator_list = []
        for arg in method.args.args: arg.annotation = None
    return ast.Module(body=selected, type_ignores=[])

ns = dict(asyncio=asyncio, SettingsFrame=SettingsFrame, HeadersFrame=HeadersFrame,
    WindowUpdateFrame=WindowUpdateFrame, DataFrame=DataFrame, XpcWrapper=xpc.XpcWrapper,
    XpcFlags=xpc.XpcFlags, XpcUInt64Type=xpc.XpcUInt64Type,
    HTTP2_MAGIC=b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n',
    DEFAULT_SETTINGS_MAX_CONCURRENT_STREAMS=100, DEFAULT_SETTINGS_INITIAL_WINDOW_SIZE=16*1024*1024,
    DEFAULT_WIN_SIZE_INCR=16*1024*1024-65535, ROOT_CHANNEL=1, REPLY_CHANNEL=3,
    FIRST_REPLY_TIMEOUT=3, ProtocolError=RuntimeError,
    MESSAGING_PROTOCOL_VERSION=7, REMOTE_XPC_VERSION_FLAGS=0x0100000000000006)
for node in ast.parse(remote.read_text()).body:
    if isinstance(node, ast.Assign):
        for target in node.targets:
            if isinstance(target, ast.Name) and target.id in ('MESSAGING_PROTOCOL_VERSION', 'REMOTE_XPC_VERSION_FLAGS'):
                ns[target.id] = ast.literal_eval(node.value)
exec(compile(methods(remote, 'RemoteXPCConnection', ['_do_handshake', 'send_device_handshake']), str(remote), 'exec'), ns)
class Writer:
    def __init__(self): self.data=bytearray()
    def write(self, data): self.data.extend(data)
    async def drain(self): pass
class Peer:
    def __init__(self): self.writer=Writer(); self.frames=[]; self.next_message_id={1:0,3:0}
    async def _send_frame(self, frame): self.frames.append(frame); self.writer.write(frame.serialize())
    async def send_request(self, obj):
        await self._send_frame(DataFrame(stream_id=1, data=xpc.create_xpc_wrapper(obj, message_id=self.next_message_id[1])))
        self.next_message_id[1]+=1
    async def _receive_frame(self): return SettingsFrame()
    def _apply_flow_control_frame(self, frame): return True
peer=Peer()
asyncio.run(ns['_do_handshake'](peer))
peer.frames[0].settings[SettingsFrame.INITIAL_WINDOW_SIZE]=16384
handshake=ns['HTTP2_MAGIC']+b''.join(f.serialize() for i,f in enumerate(peer.frames) if i != 1)
identity=uuid.UUID('00112233-4455-6677-8899-aabbccddeeff')
asyncio.run(ns['send_device_handshake'](peer, identity))
hello=peer.frames[-1].serialize()
hello_parsed=xpc.XpcWrapper.parse(peer.frames[-1].data)
assert hello_parsed.message.message_id == 1 and int.from_bytes(peer.frames[-1].data[4:8], 'little')==0x101

screen='com.apple.coredevice.screencaptureservice'
display='com.apple.coredevice.displayservice'
universal='com.apple.coredevice.hid.universalhidservice'
indigo='com.apple.coredevice.hid.indigo'
capture='com.apple.coredevice.feature.capturescreenshot'
media='com.apple.coredevice.feature.startmediastream'
base={'Properties': {'UniqueDeviceID':'SYNTHETIC-DO-NOT-RETAIN', 'ProductType':'FakePhone'},
    'Services': {
        screen: {'Port':'61001','Properties': {'UsesRemoteXPC':True,'Features':[capture]}},
        display: {'Port':xpc.XpcUInt64Type(61002),'Properties':{'UsesRemoteXPC':True,'Features':[media]}},
        universal: {'Port':xpc.XpcInt64Type(61003)},
        indigo: {'Port':'61004', 'Properties':{'Features':[]}},
        'unrelated.service': {'PrivateValue':'DO-NOT-RETAIN'},
    }}
class MissingService(Exception): pass
class UnsupportedFeature(Exception): pass
rules={'InvalidServiceError':MissingService, 'DeviceFeatureNotSupportedError':UnsupportedFeature}
exec(compile(methods(rsd_path,'RemoteServiceDiscoveryService', ['get_service_port','require_feature','_get_service_entry']),str(rsd_path),'exec'), rules)
class Ref:
    def __init__(self, info): self.info=info;self.udid='synthetic';self.product_version='0'
    def _require_peer_info(self): return self.info
    _get_service_entry=rules['_get_service_entry']
    get_service_port=rules['get_service_port']
    require_feature=rules['require_feature']
r=Ref(base)
assert [r.get_service_port(n) for n in (screen,display,universal,indigo)] == [61001,61002,61003,61004]
r.require_feature(screen,capture); r.require_feature(indigo,'anything'); r.require_feature(universal,'anything')
try: r.require_feature(display,'com.apple.coredevice.feature.stopmediastream')
except UnsupportedFeature: pass
else: raise AssertionError('pinned feature denial changed')

def wrapper(value, message_id=99): return xpc.create_xpc_wrapper(value,message_id=message_id)
def one_entry(value): return {'Services':{screen:value}}
fixtures={'transport_handshake':handshake,'device_handshake':hello,'peer_info':wrapper(base),
    'empty':wrapper({}),
    'no_payload':xpc.XpcWrapper.build({'flags':1,'message':{'message_id':0,'payload':None}}),
    'answer':wrapper({'answer':xpc.XpcUInt64Type(7)},1),
    'max_id':wrapper(base,(1 << 64)-1),
    'missing':wrapper({'Services':{}}),
    'unknown_features':wrapper(one_entry({'Port':'61001'})),
    'null_features':wrapper(one_entry({'Port':'61001','Properties':{'Features':None}})),
    'empty_features':wrapper(one_entry({'Port':'61001','Properties':{'Features':[]}})),
    'wrong_transport':wrapper(one_entry({'Port':'61001','Properties':{'UsesRemoteXPC':False}})),
    'no_services':wrapper({'Properties':{}}),
    'bad_services':wrapper({'Services':[]}),
    'bad_entry':wrapper(one_entry('wrong')),
    'missing_port':wrapper(one_entry({})),
    'bad_properties':wrapper(one_entry({'Port':'61001','Properties':[]})),
    'bad_transport_type':wrapper(one_entry({'Port':'61001','Properties':{'UsesRemoteXPC':'true'}})),
    'bad_features_type':wrapper(one_entry({'Port':'61001','Properties':{'Features':capture}})),
    'bad_feature_entry':wrapper(one_entry({'Port':'61001','Properties':{'Features':[True]}})),
}
for name, port in [('zero','0'),('high','65536'),('space',' 12'),('sign','+12'),('empty_port',''),
    ('long_port','000001'),('hex','0xff'),('negative',xpc.XpcInt64Type(-1)),
    ('highint',xpc.XpcUInt64Type(65536)),('boolport',True),('nullport',None)]:
    fixtures[name]=wrapper(one_entry({'Port':port}))
# Unknown, large metadata validates but is discarded; no full peer-info retained.
large=dict(base, Extra=bytes(60000))
fixtures['large_info']=wrapper(large)
assert len(fixtures['large_info']) < 65536
base_size = len(wrapper(dict(base, Extra=b'')))
fixtures['limit_info'] = wrapper(dict(base, Extra=bytes(65536-base_size)))
assert len(fixtures['limit_info']) == 65536
fixtures['over_limit']=wrapper(dict(base, Extra=bytes(65536)))[:24]
out=Path('.build/rsd-fixtures');out.mkdir(parents=True,exist_ok=True)
lines=[]
for name, data in fixtures.items():
    if name in ('large_info', 'limit_info'): (out/(name+'.bin')).write_bytes(data); continue
    lines.append('static const uint8_t fixture_%s[]={%s};'%(name,','.join(str(v) for v in data)))
(out/'rsd_fixtures.h').write_text('\n'.join(lines)+'\n')
print('RSD: pinned handshake AST wire comparison + service-port/feature source behavior; synthetic peer fixtures')
